import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Dyi9RH6t.js";var i=JSON.parse(`{"title":"Use RECORD in Holodeck Mocks","description":"","frontmatter":{},"headers":[],"relativePath":"skills/holodeck/using-record.md","filePath":"skills/holodeck/using-record.md"}`),a={name:`skills/holodeck/using-record.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="use-record-in-holodeck-mocks" tabindex="-1">Use RECORD in Holodeck Mocks <a class="header-anchor" href="#use-record-in-holodeck-mocks" aria-label="Permalink to “Use RECORD in Holodeck Mocks”">​</a></h1><p>Use this skill when a test mocks HTTP with <code>@warp-drive/holodeck</code> and you need to re-record one request, or when you are reviewing a test that sets <code>RECORD</code>. <code>RECORD</code> is a per-request override. It is a local tool for refreshing a fixture, not a setting a committed test should carry.</p><h2 id="how-recording-is-decided" tabindex="-1">How recording is decided <a class="header-anchor" href="#how-recording-is-decided" aria-label="Permalink to “How recording is decided”">​</a></h2><p>Holodeck records or replays according to a build-time flag from <code>@warp-drive/build-config</code>.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SHOULD_RECORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> IS_RECORDING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>A local run records every mock. A run with <code>CI</code> set replays every mock from <code>.mock-cache</code>. <code>RECORD</code> overrides that for a single mock: it records the request even when the rest of the suite replays.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li><p>Rely on the default first. To change a response, edit the mock and run the suite locally. It re-records without any option.</p></li><li><p>Reach for <code>RECORD</code> only when one request has to record while the suite replays, for example when you run with <code>CI=1</code> locally and need a single fixture refreshed.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;users/1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({ data: { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }), { RECORD: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p><code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>, and <code>HEAD</code> take the same option. The low-level form is <code>mock(this, generate, true)</code>.</p></li><li><p>Run the test, then commit the fixture it wrote under <code>.mock-cache</code>.</p></li><li><p>Delete <code>RECORD</code> from the test before you commit the test.</p></li><li><p>Prove the fixture replays. <code>CI</code> is compiled into the test bundle, so set it on the command that builds as well as the one that runs.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:tests</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div></li></ol><h2 id="why-record-must-not-be-committed" tabindex="-1">Why RECORD must not be committed <a class="header-anchor" href="#why-record-must-not-be-committed" aria-label="Permalink to “Why RECORD must not be committed”">​</a></h2><p>A committed <code>RECORD: true</code> records that request in every environment, CI included. The request is never compared against its committed fixture again, so the test passes whatever that fixture says, and a stale or wrong fixture goes unnoticed. The rest of the suite still replays, which makes the one exception easy to miss in review.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>With <code>RECORD</code>, the response generator runs even in replay. Without it, replay never calls the generator, which is what makes a replayed suite cheap.</li><li>A test that declares a mock and never requests it fails from <code>afterEach</code>, with or without <code>RECORD</code>.</li><li>Treat <code>RECORD</code> in a diff the way you treat a focused or skipped test: ask for it to be removed before merge.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li>Full guide: <a href="/pr-preview/pr-11292/guides/the-manual/testing/record-and-replay">Recording and Replaying</a></li><li>Related skills: <a href="/pr-preview/pr-11292/skills/holodeck/mock-http-requests-in-tests">Mock HTTP Requests in Tests</a> for the helpers that take this option, and <a href="/pr-preview/pr-11292/skills/requests/fetch-and-cache-data">Fetch and Cache Data</a></li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};